  function iuNormalizeYouTubeId(v){
    const s = (v || "").trim();
    if (/^[a-zA-Z0-9_-]{11}$/.test(s)) return s;
    const m1 = s.match(/[?&]v=([a-zA-Z0-9_-]{11})/);
    if (m1) return m1[1];
    const m2 = s.match(/youtu\.be\/([a-zA-Z0-9_-]{11})/);
    if (m2) return m2[1];
    const m3 = s.match(/shorts\/([a-zA-Z0-9_-]{11})/);
    if (m3) return m3[1];
    return "";
  }

