    var fresh = d.coverageEvidenceFresh === true ? "ano" : (d.stale === true ? "evidence není dostatečně čerstvá" : "—");
    var lastReviewedAt = d.lastReviewedAt != null && d.lastReviewedAt !== "" ? String(d.lastReviewedAt) : "—";
