    if (/\bobchodn\w*\s+vec\b/.test(s)) return true;
    if (/\bjednan\w*\b/.test(s)) return true;
    if (/\bkontrola\b/.test(s)) return true;
    if (/\bsmlouv\w*\b/.test(s)) return true;
    if (/\badresa\b/.test(s)) return true;
