    if (/\bnajdi\s+poznam\w*\s+o\s+\w/.test(x)) return true;
    if (/\bco\s+mam\s+k\s+\w+/.test(x) && /\b(zaruk\w*|zaruc\w*|reklamac\w*|pojist\w*|smlouv\w*|faktur\w*|servis\w*)\b/.test(x)) return true;
