  function stripNote(raw) {
    const patterns = [
      /\s+a\s+pozn[aá]mk[aá]?\s+(.+)$/i,
      /\s+a\s+do\s+pozn[aá]m(?:ek|ky|ce)\b\s+mi\s+(?:dej|ulož|uloz|zapiš|zapis|přidej|pridej|hoď|hod)\s+(.+)$/i,
      /\s+k\s+tomu\s+do\s+pozn[aá]m(?:ek|ky|ce)\b\s+(?:dej|mi\s+dej|ulož|uloz|zapiš|zapis|přidej|pridej)\s+(.+)$/i,
      /\s+a\s+do\s+pozn[aá]m(?:ek|ky|ce)\b\s+(?:dej|ulož|uloz|zapiš|zapis|přidej|pridej|hoď|hod)\s+(.+)$/i,
      /\bdo\s+pozn[aá]mky\s+(.+?)\s+a\s+adresa\s+je\b/i,
      /\bdo\s+pozn[aá]mky\s+(.+?)(?=\s+adresa\s+je\b)/i,
      /\ba\s+do\s+pozn[aá]mky\s+napi[sš]\s+(.+)$/i,
      /\bdo\s+pozn[aá]mky\s+dej\s+(.+)$/i,
      /\bpozn[aá]mka\s*:\s*(.+)$/i,
      /\bdo\s+pozn[aá]mky\s+(.+)$/i
    ];
    let note = "";
    let out = String(raw || "");
    for (const re of patterns) {
      const m = out.match(re);
      if (m && m[1]) {
        note = String(m[1]).trim().slice(0, 1000);
        out = out.replace(re, " ");
        break;
      }
    }
    return { work: out.replace(/\s+/g, " ").trim(), note };
  }

  function iuSilverHumanizeRoughNote(s) {
    let t = iuSilverNormalizeWs(String(s || ""));
    t = t.replace(/^\s*ulo[žz](?:te)?\s+/i, "").trim();
    if (!t) return "";
    t = t
      .replace(/\bvezmi\b/gi, "vzít")
      .replace(/\bvzit\b/gi, "vzít")
      .replace(/\bsesit\b/gi, "sešit")
      .replace(/\bse[sš]it\b/gi, "sešit");
    return (t.charAt(0).toLocaleUpperCase("cs-CZ") + t.slice(1)).slice(0, 1000);
  }

  function stripLoosePackNote(work) {
    const s = String(work || "");
    const re = /\s+(?:vz[ií]t|vzit)\s+(?:sebou\s+)?(?:se[sš]it|sesit)\s*$/i;
    const m = s.match(re);
    if (!m || m.index == null) return { work: s.replace(/\s+/g, " ").trim(), note: "" };
    const main = s.slice(0, m.index).replace(/\s+/g, " ").trim();
    const noteRaw = s.slice(m.index).trim();
    return { work: main, note: iuSilverHumanizeRoughNote(noteRaw) };
  }

  /** P0: kalendářová věta + „ať si vezmu / nezapomenout vzít …“ → text do pole poznámky události, ne samostatná poznámka. */
  function iuSilverStripEmbeddedEventPackTailFromCalendarWorkP0(work) {
    const s0 = String(work || "").trim();
    if (!s0) return { work: "", note: "" };
    const pats = [
      /\s+a[tť]\s+si\s+vez(mu|mi)\b[\s\S]+$/i,
      /\s+a(?:by)?ch\s+si\s+(?:sebou\s+)?vzal\w*\b[\s\S]+$/i,
      /\s+nezapomen(?:out)?\s+vz[ií]t\w*\b[\s\S]+$/i
    ];
    for (let pi = 0; pi < pats.length; pi++) {
      const m = s0.match(pats[pi]);
      if (m && typeof m.index === "number" && m.index >= 1) {
        const noteRaw = s0.slice(m.index).trim();
        const main = s0.slice(0, m.index).replace(/\s+/g, " ").trim();
        return { work: main, note: iuSilverHumanizeRoughNote(noteRaw) };
      }
    }
    return { work: s0.replace(/\s+/g, " ").trim(), note: "" };
  }

  /** P0 real mobile: připomenutí v kalendářové větě → pole poznámky události, ne název. */
  function iuSilverStripCalendarReminderClauseFromWork(work) {
    const s0 = String(work || "").trim();
    if (!s0) return { work: "", rem: "" };
    const re = /\s+(?:a\s+)?p[rř]ipome[nň](?:te)?\s+mi(?:\s+a[ťt])?\s+.+/i;
    const m = s0.match(re);
    if (!m || m.index == null || m.index < 1) return { work: s0, rem: "" };
    const rem = s0.slice(m.index).trim();
    const main = s0.slice(0, m.index).replace(/\s+/g, " ").trim();
    return { work: main, rem: rem };
  }

  function stripDuration(work) {
    let w = work;
    let minutes = null;
    const mMin = w.match(/\bna\s+(\d{1,3})\s*minut/u);
    if (mMin) {
      minutes = Math.max(1, Number(mMin[1]) || 0);
      w = w.replace(mMin[0], " ");
    }
    if (minutes == null) {
      const mH = w.match(/\bna\s+1\s*hodin/u);
      const mH2 = w.match(/\bna\s+hodinu\b/u);
      if (mH || mH2) {
        minutes = 60;
        w = w.replace(mH ? mH[0] : mH2[0], " ");
      }
    }
    return { work: w.replace(/\s+/g, " ").trim(), minutes };
  }

  /**
   * P1 narrow: české místo konání z kalendářové věty → location (Quality Audit V2 address_in_title_only).
   * Jen deterministické vzory (na mostě / náměstí / nádraží / Korunní / kavárna / restaurace / Brno centrum).
   * Nebere slepě každé „v …“ (vyloučeno v patternu). Volá se z stripLocation až po standardních místních vzorech.
   */
  function iuSilverTryStripNarrowCalendarVenueTail(wIn) {
    let w = String(wIn || "").trim();
    if (!w) return { work: w, location: "" };
    const specs = [
      { re: /\bv centru Brna\s+na\s+náměstí\s+Svobody(?=,|\s|$|\.|!|\?)/i, loc: "Brno náměstí Svobody" },
      { re: /\bna\s+Mánesovém\s+mostě(?:\s+v\s+Praze)?(?=,|\s|$|\.|!|\?)/i, loc: "Mánesův most Praha" },
      { re: /\bna\s+Karlově\s+mostě(?=,|\s|$|\.|!|\?)/i, loc: "Karlův most Praha" },
      {
        re: /\bna\s+Václavském\s+náměstí\s+(\d+)\s+Praha(?=,|\s|$|\.|!|\?)/i,
        locFrom: function (m) {
          return "Václavské náměstí " + String(m[1] || "").trim() + " Praha";
        }
      },
      { re: /\bna\s+Hlavním\s+nádraží\s+Praha(?=,|\s|$|\.|!|\?)/i, loc: "Hlavní nádraží Praha" },
      { re: /\bv\s+kav[aá]rně\s+Louvre(?:\s+Praha)?(?=,|\s|$|\.|!|\?)/i, loc: "Kavárna Louvre Praha" },
      { re: /\bv\s+restaurac[ei]\s+Marina\s+Praha(?=,|\s|$|\.|!|\?)/i, loc: "Restaurace Marina Praha" },
      { re: /\brestaurac[ei]\s+Marina\s+Praha(?=,|\s|$|\.|!|\?)/i, loc: "Restaurace Marina Praha" },
      {
        re: /\bna\s+Korunní\s+(\d+)(?:\s+Praha)?(?=,|\s|$|\.|!|\?)/i,
        locFrom: function (m) {
          return "Korunní " + String(m[1] || "").trim() + " Praha";
        }
      },
      {
        re: /\bna\s+([A-ZÁČÉĚÍŇÓŘŠŤÚŮÝŽa-záčéěíňóřšťúůýž]+(?:ov|ovém|ové|ém|ě)?\s+mostě)(?:\s+v\s+Praze)?(?=,|\s|$|\.|!|\?)/i,
        locFrom: function (m) {
          const core = String(m[1] || "").trim();
          if (!core) return "";
          return core + " Praha";
        }
      }
    ];
    for (let si = 0; si < specs.length; si++) {
      const sp = specs[si];
      const m = w.match(sp.re);
      if (!m) continue;
      let loc = sp.locFrom ? sp.locFrom(m) : sp.loc;
      loc = iuSilverNormalizeWs(String(loc || "")).slice(0, 200);
      if (loc.length >= 6) {
        w = iuSilverNormalizeWs(w.replace(sp.re, " "));
        return { work: w, location: loc };
      }
    }
    return { work: w, location: "" };
  }

  /** P0: oříznutí omylu „místo + , ne do úkolů“ zachyceného do location (kalendářová věta). */
  function iuSilverTrimTrailingNeDoFromCalendarLoc(s) {
    let t = iuSilverNormalizeWs(String(s || ""));
    t = t.replace(/\s*,\s*ne\s+do\b[\s\S]*$/i, "").trim();
    return t.replace(/[,.;:!?]+$/g, "").trim();
  }

