        draft.targetContainer === "tasks" ? "task" : draft.targetContainer === "notes" ? "note" : "calendar";
      const cap = kind === "task" ? 200 : 120;
      let outT = normalizeSilverTitleV1(fin.text, { kind: kind }).slice(0, cap);
