  function extractFromUtterance(raw, now) {
    const values = { date: "", time: "", title: "", note: "", location: "", durationMinutes: null };
    const confidence = {
      date: "missing",
      time: "missing",
      title: "missing",
      note: "optional",
      location: "optional",
      duration: "optional"
    };

    const rawCtx = String(raw || "").trim();
    let work = iuSilverNormalizeCzechNumberWords(rawCtx);
    work = iuSilverStripCalendarCorrectionWriteBoilerplate(work);
    const notePieces = [];

    const noteHit = stripNote(work);
    if (noteHit.note) {
      notePieces.push(iuSilverHumanizeRoughNote(noteHit.note));
      confidence.note = "certain";
    }
    work = noteHit.work;

    const looseNote = stripLoosePackNote(work);
    if (looseNote.note) {
      notePieces.push(looseNote.note);
      confidence.note = "certain";
    }
    work = looseNote.work;

    const packTail = iuSilverStripEmbeddedEventPackTailFromCalendarWorkP0(work);
    if (packTail.note) {
      notePieces.push(packTail.note);
      confidence.note = "certain";
    }
    work = packTail.work;

    const remStrip = iuSilverStripCalendarReminderClauseFromWork(work);
    if (remStrip.rem) {
      notePieces.push(iuSilverHumanizeRoughNote(remStrip.rem));
      confidence.note = "certain";
    }
    work = remStrip.work;

    const durHit = stripDuration(work);
    if (durHit.minutes != null) {
      values.durationMinutes = durHit.minutes;
      confidence.duration = "certain";
    }
    work = durHit.work;

    const locHit = stripLocation(work);
    if (locHit.location) {
      values.location = locHit.location;
      confidence.location = "certain";
    }
    work = locHit.work;

    function consumeTimeFromWork() {
      const th = findTime(work, now, rawCtx);
      if (th.time) {
        values.time = th.time;
        confidence.time = "certain";
        if (th.dateISOHint && confidence.date === "missing") {
          values.date = th.dateISOHint;
          confidence.date = "certain";
        }
        work = th.work;
        return true;
      }
      return false;
    }

    consumeTimeFromWork();

    const abs = findAbsoluteDate(work, now);
    if (abs) {
      values.date = abs.date;
      confidence.date = "certain";
      work = abs.work;
    }
    if (confidence.date === "missing") {
      const rel = findRelativeDay(work, now, confidence.time === "certain", values.time);
      if (rel) {
        values.date = rel.date;
        confidence.date = "certain";
        work = rel.work;
      }
    }

    if (confidence.time !== "certain") {
      consumeTimeFromWork();
    }

    if (confidence.date === "missing") {
      const bare = tryConsumeLeadingCalendarDay(work, now);
      if (bare) {
        values.date = bare.date;
        confidence.date = "certain";
        work = bare.work;
      }
    }

    if (confidence.time !== "certain") {
      consumeTimeFromWork();
    }

    const fin = iuSilverTitlePipelineFull(work, { calendarConversationalTitleStrip: true });
    if (fin.ok) {
      values.title = fin.text;
      confidence.title = "certain";
    } else {
      values.title = "";
      confidence.title = "missing";
    }

    if (confidence.date === "missing" && confidence.time === "certain") {
      values.date = toDateOnly(now);
      confidence.date = "certain";
    }

    if (notePieces.length) {
      values.note = iuSilverNormalizeWs(notePieces.join(" ").replace(/\s+/g, " ")).slice(0, 1000);
      confidence.note = "certain";
    }

    return { values, confidence };
  }

