    if (/^(?:ze|že|ze\s+mam|ze\s+m[aá]m|že\s+mám)\b/.test(f)) return true;
    if (/^(?:napi[sš]|dej|ulo[zž]|pridej|p[rř]idej)\s+(?:ze|že)\b/.test(f)) return true;
